ALTER TABLE publications ADD COLUMN incomplete_group_key text, ADD COLUMN incomplete_group_owner text, ADD COLUMN incomplete_group_ready boolean NOT NULL DEFAULT false, ADD COLUMN incomplete_group_unknown boolean NOT NULL DEFAULT false, ADD COLUMN incomplete_group_conflict boolean NOT NULL DEFAULT false;
CREATE INDEX publications_incomplete_groups ON publications((incomplete_group_key COLLATE "C"),id COLLATE "C") WHERE incomplete_group_key IS NOT NULL;
CREATE INDEX publications_incomplete_group_recovery ON publications(id) WHERE viewed=0 AND complete=1 AND NOT source_deleted AND incomplete_class IS DISTINCT FROM 1 AND NOT incomplete_group_ready;
CREATE INDEX publications_incomplete_group_unknown ON publications(id) WHERE incomplete_group_unknown;
CREATE INDEX reader_incomplete_objects_gin ON reader_problems USING gin ((body::jsonb->'objects') jsonb_path_ops) WHERE finished IS NULL AND body::jsonb->>'code'='material-incomplete';
CREATE INDEX reader_incomplete_group_isolated ON reader_problems ((body::jsonb->>'incomplete_group_identity'),created,id COLLATE "C") WHERE finished IS NULL AND body::jsonb->>'operation'='producer:incomplete';
CREATE INDEX jobs_incomplete_profile_event ON jobs(feed_id,kind,item) WHERE problem_code IN ('identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch');
CREATE INDEX publications_incomplete_group_owner ON publications(incomplete_group_owner,id) WHERE incomplete_group_key IS NOT NULL;
CREATE INDEX reader_incomplete_reservations ON reader_problems ((body::jsonb->>'incomplete_group_identity'),id COLLATE "C") WHERE finished IS NOT NULL AND body::jsonb->>'operation'='producer:incomplete-reservation';
CREATE INDEX feeds_incomplete_youtube ON feeds(id) WHERE kind='youtube';
CREATE INDEX jobs_incomplete_caption_pending ON jobs(item) WHERE kind='download_media' AND status='pending' AND problem_code IS NULL;
CREATE INDEX reader_incomplete_legacy_recovery ON reader_problems(id COLLATE "C") WHERE finished IS NULL AND left(identity,11)='incomplete:' AND body::jsonb->>'code'='material-incomplete' AND coalesce(body::jsonb->>'operation','producer:status')='producer:status';
CREATE INDEX reader_incomplete_reservations_due ON reader_problems(finished,id COLLATE "C") WHERE finished IS NOT NULL AND body::jsonb->>'operation'='producer:incomplete-reservation';
ALTER TABLE reader_problems ADD COLUMN incomplete_due double precision, ADD COLUMN incomplete_future text, ADD COLUMN incomplete_closes boolean NOT NULL DEFAULT false;
CREATE INDEX reader_incomplete_current_due ON reader_problems(incomplete_due) WHERE finished IS NULL AND incomplete_due IS NOT NULL;
CREATE INDEX reader_incomplete_due ON reader_problems(incomplete_due,id COLLATE "C") WHERE incomplete_due IS NOT NULL;
CREATE INDEX reader_problem_nonreserve_expiry ON reader_problems(finished,id) WHERE finished IS NOT NULL AND incomplete_due IS NULL;
CREATE INDEX publications_incomplete_group_conflict ON publications(id) WHERE incomplete_group_conflict;
CREATE INDEX jobs_incomplete_youtube_fetch_error ON jobs(item) WHERE kind='fetch' AND problem_code IS NULL AND error IS NOT NULL AND status IN ('pending','running','failed','unavailable','blocked');
CREATE INDEX jobs_incomplete_youtube_media_error ON jobs(item) WHERE kind='download_media' AND problem_code IS NULL AND error IS NOT NULL AND status IN ('pending','running','failed','unavailable','blocked');
CREATE INDEX reader_incomplete_virtual_expiry ON reader_problems(incomplete_due) WHERE finished IS NULL AND incomplete_closes;
ALTER TABLE jobs ADD COLUMN incomplete_youtube_sensitive boolean NOT NULL DEFAULT false;
CREATE INDEX jobs_incomplete_youtube_sensitive ON jobs(item) WHERE kind='fetch' AND incomplete_youtube_sensitive;
